import io
import unittest

def is_even(n):
    return n % 2 == 0

class TestEven(unittest.TestCase):
    def test_even(self):
        self.assertTrue(is_even(4))

    def test_odd(self):
        self.assertFalse(is_even(3))

    def test_zero(self):
        self.assertEqual(is_even(0), True)

suite = unittest.defaultTestLoader.loadTestsFromTestCase(TestEven)
result = unittest.TextTestRunner(stream=io.StringIO()).run(suite)
print(result.testsRun, result.wasSuccessful())

import io
import unittest

class TestStack(unittest.TestCase):
    def setUp(self):
        self.items = []          # свежее окружение перед каждым тестом

    def test_push(self):
        self.items.append(1)
        self.assertEqual(self.items, [1])

    def test_empty(self):
        self.assertEqual(self.items, [])

    def test_table(self):
        for a, b, want in [(1, 2, 3), (2, 2, 4), (5, 5, 11)]:
            with self.subTest(a=a, b=b):
                self.assertEqual(a + b, want)

suite = unittest.defaultTestLoader.loadTestsFromTestCase(TestStack)
result = unittest.TextTestRunner(stream=io.StringIO()).run(suite)
print(result.testsRun, len(result.failures))

import io
import unittest

def divide(a, b):
    if b == 0:
        raise ValueError("деление на ноль")
    return a / b

class T(unittest.TestCase):
    def test_error(self):
        with self.assertRaises(ValueError) as ctx:
            divide(1, 0)
        self.assertIn("ноль", str(ctx.exception))

    def test_edges(self):
        self.assertEqual(divide(0, 5), 0)
        self.assertEqual(divide(-6, 3), -2)

r = unittest.TextTestRunner(stream=io.StringIO()).run(unittest.defaultTestLoader.loadTestsFromTestCase(T))
print(r.testsRun, r.wasSuccessful())

from unittest.mock import Mock, patch
import random

def get_price(session, item):
    return session.get(item)["price"]

fake = Mock()
fake.get.return_value = {"price": 100}
print(get_price(fake, "кофе"))
fake.get.assert_called_once_with("кофе")

def roll():
    return random.randint(1, 6)

with patch("random.randint", return_value=4):
    print(roll())
print(1 <= roll() <= 6)

# 1. красный: тест пишем первым
def test_fizz():
    assert fizzbuzz(3) == "Fizz"
    assert fizzbuzz(5) == "Buzz"
    assert fizzbuzz(15) == "FizzBuzz"
    assert fizzbuzz(7) == "7"

# 2. зелёный: минимальный код
def fizzbuzz(n):
    if n % 15 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    return str(n)

test_fizz()
print("зелёный")

